// Regenerate src/art/index.ts from the art files present.
//   node --experimental-strip-types --no-warnings scripts/gen-art-index.ts
import { readdirSync, writeFileSync } from "node:fs";

const SKIP = new Set(["index", "types", "style"]);
const ids = readdirSync("src/art")
  .filter((f) => f.endsWith(".ts") && !f.startsWith("_"))
  .map((f) => f.slice(0, -3))
  .filter((id) => !SKIP.has(id) && /^[a-z0-9_]+$/.test(id))
  .sort();
const lines = [
  "// Generated by scripts/gen-art-index.ts — do not edit by hand.",
  'import type { Art } from "./types.ts";',
  ...ids.map((id) => `import ${id} from "./${id}.ts";`),
  "",
  `export const ART: Record<string, Art> = { ${ids.join(", ")} };`,
  "",
];
writeFileSync("src/art/index.ts", lines.join("\n"));
console.log(`${ids.length} charges: ${ids.join(" ")}`);
